import * as vscode from 'vscode';
import { LanguageClient, ServerOptions, TransportKind } from 'vscode-languageclient/node';
import { $Knc, $Lnc } from './client/client';
import { $Aoc } from './extension.shared';
import { $jnc } from './logging';
import { IMdParser, $rnc } from './markdownEngine';
import { $mnc } from './markdownExtensions';
import { $onc } from './slugify';

export async function activate(context: vscode.ExtensionContext) {
	const contributions = $mnc(context);
	context.subscriptions.push(contributions);

	const logger = new $jnc();
	context.subscriptions.push(logger);

	const engine = new $rnc(contributions, $onc, logger);

	const client = await startServer(context, engine);
	context.subscriptions.push(client);
	$Aoc(context, client, engine, logger, contributions);
}

function startServer(context: vscode.ExtensionContext, parser: IMdParser): Promise<$Knc> {
	const clientMain = vscode.extensions.getExtension('vscode.markdown-language-features')?.packageJSON?.main || '';

	const serverMain = `./server/${clientMain.indexOf('/dist/') !== -1 ? 'dist' : 'out'}/node/workerMain`;
	const serverModule = context.asAbsolutePath(serverMain);

	// The debug options for the server
	const debugOptions = { execArgv: ['--nolazy', '--inspect=' + (7000 + Math.round(Math.random() * 999))] };

	// If the extension is launch in debug mode the debug server options are use
	// Otherwise the run options are used
	const serverOptions: ServerOptions = {
		run: { module: serverModule, transport: TransportKind.ipc },
		debug: { module: serverModule, transport: TransportKind.ipc, options: debugOptions }
	};

	// pass the location of the localization bundle to the server
	process.env['VSCODE_L10N_BUNDLE_LOCATION'] = vscode.l10n.uri?.toString() ?? '';

	return $Lnc((id, name, clientOptions) => {
		return new LanguageClient(id, name, serverOptions, clientOptions);
	}, parser);
}
