import * as vscode from 'vscode';
import { $pnc } from '../../util/schemes';
import { $coc, $_nc, $$nc } from './shared';

class PasteEditProvider implements vscode.DocumentPasteEditProvider {

	private readonly a = 'insertLink';

	async provideDocumentPasteEdits(
		document: vscode.TextDocument,
		ranges: readonly vscode.Range[],
		dataTransfer: vscode.DataTransfer,
		token: vscode.CancellationToken,
	): Promise<vscode.DocumentPasteEdit | undefined> {
		const enabled = vscode.workspace.getConfiguration('markdown', document).get('editor.filePaste.enabled', true);
		if (!enabled) {
			return;
		}

		const createEdit = await this.b(document, dataTransfer, token);
		if (createEdit) {
			return createEdit;
		}

		const uriEdit = new vscode.DocumentPasteEdit('', this.a, '');
		const urlList = await dataTransfer.get('text/uri-list')?.asString();
		if (!urlList) {
			return;
		}
		const pasteEdit = await $_nc(document, ranges, urlList, token);
		if (!pasteEdit) {
			return;
		}

		uriEdit.label = pasteEdit.label;
		uriEdit.additionalEdit = pasteEdit.additionalEdits;
		uriEdit.priority = this.c(dataTransfer);
		return uriEdit;
	}

	private async b(document: vscode.TextDocument, dataTransfer: vscode.DataTransfer, token: vscode.CancellationToken): Promise<vscode.DocumentPasteEdit | undefined> {
		if (document.uri.scheme === $pnc.untitled) {
			return;
		}

		const copyFilesIntoWorkspace = vscode.workspace.getConfiguration('markdown', document).get<'mediaFiles' | 'never'>('editor.filePaste.copyIntoWorkspace', 'mediaFiles');
		if (copyFilesIntoWorkspace === 'never') {
			return;
		}

		const edit = await $coc(document, dataTransfer, token);
		if (!edit) {
			return;
		}

		const pasteEdit = new vscode.DocumentPasteEdit(edit.snippet, this.a, edit.label);
		pasteEdit.additionalEdit = edit.additionalEdits;
		pasteEdit.priority = this.c(dataTransfer);
		return pasteEdit;
	}

	private c(dataTransfer: vscode.DataTransfer): number {
		if (dataTransfer.get('text/plain')) {
			// Deprioritize in favor of normal text content
			return -10;
		}
		return 0;
	}
}

export function $qoc(selector: vscode.DocumentSelector,) {
	return vscode.languages.registerDocumentPasteEditProvider(selector, new PasteEditProvider(), {
		pasteMimeTypes: [
			'text/uri-list',
			...$$nc,
		]
	});
}
