import * as vscode from 'vscode';
import { Command } from '../commandManager';
import { $4nc } from '../preview/previewManager';

export class $loc implements Command {
	public readonly id = '_markdown.copyImage';

	public constructor(
		private readonly a: $4nc,
	) { }

	public execute(args: { id: string; resource: string }) {
		const source = vscode.Uri.parse(args.resource);
		this.a.findPreview(source)?.copyImage(args.id);
	}
}
