import * as vscode from 'vscode';

export function $hnc(disposables: Iterable<vscode.Disposable>) {
	const errors: any[] = [];

	for (const disposable of disposables) {
		try {
			disposable.dispose();
		} catch (e) {
			errors.push(e);
		}
	}

	if (errors.length === 1) {
		throw errors[0];
	} else if (errors.length > 1) {
		throw new AggregateError(errors, 'Encountered errors while disposing of store');
	}
}

export interface IDisposable {
	dispose(): void;
}

export abstract class $inc {
	private c = false;

	protected d: vscode.Disposable[] = [];

	public dispose(): any {
		if (this.c) {
			return;
		}
		this.c = true;
		$hnc(this.d);
	}

	protected f<T extends IDisposable>(value: T): T {
		if (this.c) {
			value.dispose();
		} else {
			this.d.push(value);
		}
		return value;
	}

	protected get g() {
		return this.c;
	}
}
