import * as vscode from 'vscode';
import { $coc as $coc, $$nc, $aoc } from './shared';
import { $pnc } from '../../util/schemes';


class MarkdownImageDropProvider implements vscode.DocumentDropEditProvider {
	private readonly a = 'insertLink';

	async provideDocumentDropEdits(document: vscode.TextDocument, _position: vscode.Position, dataTransfer: vscode.DataTransfer, token: vscode.CancellationToken): Promise<vscode.DocumentDropEdit | undefined> {
		const enabled = vscode.workspace.getConfiguration('markdown', document).get('editor.drop.enabled', true);
		if (!enabled) {
			return;
		}

		const filesEdit = await this.c(document, dataTransfer, token);
		if (filesEdit) {
			return filesEdit;
		}

		if (token.isCancellationRequested) {
			return;
		}

		return this.b(document, dataTransfer, token);
	}

	private async b(document: vscode.TextDocument, dataTransfer: vscode.DataTransfer, token: vscode.CancellationToken): Promise<vscode.DocumentDropEdit | undefined> {
		const urlList = await dataTransfer.get('text/uri-list')?.asString();
		if (!urlList) {
			return undefined;
		}
		const snippet = await $aoc(document, urlList, token);
		if (!snippet) {
			return undefined;
		}

		const edit = new vscode.DocumentDropEdit(snippet.snippet);
		edit.id = this.a;
		edit.label = snippet.label;
		return edit;
	}

	private async c(document: vscode.TextDocument, dataTransfer: vscode.DataTransfer, token: vscode.CancellationToken): Promise<vscode.DocumentDropEdit | undefined> {
		if (document.uri.scheme === $pnc.untitled) {
			return;
		}

		const copyIntoWorkspace = vscode.workspace.getConfiguration('markdown', document).get<'mediaFiles' | 'never'>('editor.drop.copyIntoWorkspace', 'mediaFiles');
		if (copyIntoWorkspace !== 'mediaFiles') {
			return;
		}

		const filesEdit = await $coc(document, dataTransfer, token);
		if (!filesEdit) {
			return;
		}

		const edit = new vscode.DocumentDropEdit(filesEdit.snippet);
		edit.id = this.a;
		edit.label = filesEdit.label;
		edit.additionalEdit = filesEdit.additionalEdits;
		return edit;
	}
}

export function $toc(selector: vscode.DocumentSelector) {
	return vscode.languages.registerDocumentDropEditProvider(selector, new MarkdownImageDropProvider(), {
		dropMimeTypes: [
			'text/uri-list',
			...$$nc,
		]
	});
}
